kdv_Hm1T_uniform_cauchy.definitions:
def WT (κ : ℝ) (f : lp (fun _ : ℤ => ℂ) 2) : ℝ :=
  ∑' n : ℤ, ((4 + (2 * π * n) ^ 2) / ((2 * π * n) ^ 2 + 4 * κ ^ 2)) * ‖f n‖ ^ 2

open scoped ContDiff in

def IsGreenT (κ : ℝ) (q g : ℝ → ℝ) : Prop :=
  ContDiff ℝ ∞ g ∧ Function.Periodic g 1 ∧ (∀ x, 0 < g x) ∧
    ∀ x, deriv g x ^ 2 - 2 * g x * iteratedDeriv 2 g x + 4 * (κ ^ 2 + q x) * g x ^ 2 = 1


def greenT (κ : ℝ) (q : ℝ → ℝ) : ℝ → ℝ :=
  if h : ∃ g : ℝ → ℝ, IsGreenT κ q g then Classical.choose h else fun _ => 1 / (2 * κ)


def hkRHST (κ : ℝ) (q : ℝ → ℝ) (x : ℝ) : ℝ :=
  16 * κ ^ 5 * deriv (greenT κ q) x + 4 * κ ^ 2 * deriv q x

open scoped ContDiff in

def IsHkSolutionT (κ : ℝ) (c : ℝ → CinfT) : Prop :=
  ContDiff ℝ ∞ (fun p : ℝ × ℝ => (c p.1 : ℝ → ℝ) p.2) ∧
    ∀ t x : ℝ, HasDerivAt (fun s : ℝ => (c s : ℝ → ℝ) x) (hkRHST κ (c t : ℝ → ℝ) x) t


def hkFlowT (κ t : ℝ) (q : CinfT) : CinfT :=
  if h : ∃ c : ℝ → CinfT, IsHkSolutionT κ c ∧ c 0 = q then Classical.choose h t else q

