hk_flow_T_exists.definitions:
def rgreenT (κ : ℝ) (w : ℝ → ℝ) (x : ℝ) : ℝ :=
  (1 - Real.exp (2 * (∫ y in (0:ℝ)..1, w y) - 2 * κ))⁻¹ *
    ∫ s in (0:ℝ)..1, Real.exp (-2 * κ * s + 2 * ∫ y in (x - s)..x, w y)


def rgreenRT (κ : ℝ) (w : ℝ → ℝ) (x : ℝ) : ℝ :=
  (1 - Real.exp (2 * (∫ y in (0:ℝ)..1, w y) - 2 * κ))⁻¹ *
    ∫ s in (0:ℝ)..1, Real.exp (-2 * κ * s + 2 * ∫ y in x..(x + s), w y)


def wfieldT (κ : ℝ) (w : ℝ → ℝ) (x : ℝ) : ℝ :=
  8 * κ ^ 5 * (rgreenT κ w x - rgreenRT κ w x)

